<div class="patient-page-heading"><div><span class="eyebrow text-secondary">HISTORIAL DEL PACIENTE</span><h1><?= $escape($history['patient']['nombres'].' '.$history['patient']['apellidos']) ?></h1><p class="text-secondary mb-0"><?= $escape($history['patient']['codigo_paciente']) ?></p></div></div>
<?php if ($success): ?><div class="alert alert-success" role="status"><?= $escape($success) ?></div><?php endif; ?>
<section class="patient-card patient-detail-section"><h2 class="h5">Datos para la atención</h2><dl class="row mb-0"><?php foreach (['documento_identidad'=>'Documento de identidad','fecha_nacimiento'=>'Fecha de nacimiento','sexo'=>'Sexo','estado'=>'Estado'] as $field=>$label): ?><div class="col-md-6 mb-3"><dt><?= $escape($label) ?></dt><dd><?= $escape($history['patient'][$field] ?: 'Sin registrar') ?></dd></div><?php endforeach; ?></dl></section>
<?php if ($history['clinical']): ?><section class="patient-card patient-detail-section"><h2 class="h5">Antecedentes y alertas médicas</h2><dl class="row mb-0"><?php foreach (['tipo_sangre'=>'Tipo de sangre','alergias'=>'Alergias','antecedentes_relevantes'=>'Antecedentes relevantes'] as $field=>$label): ?><div class="col-md-6 mb-3"><dt><?= $escape($label) ?></dt><dd><?= nl2br($escape($history['patient'][$field] ?: 'Sin registrar')) ?></dd></div><?php endforeach; ?></dl></section><?php endif; ?>
<section class="patient-card patient-detail-section"><h2 class="h5">Citas y atención</h2><?php if (!$history['appointments']): ?><p class="text-secondary mb-0">No existen citas registradas para este paciente.</p><?php else: ?><div class="table-responsive"><table class="table patient-table mb-0"><thead><tr><th>Fecha</th><th>Médico</th><th>Especialidad</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach ($history['appointments'] as $appointment): ?><tr><td><?= $escape($appointment['fecha'].' '.$appointment['hora_inicio']) ?></td><td><?= $escape($appointment['medico_nombre']) ?></td><td><?= $escape($appointment['especialidad_nombre']) ?></td><td><?= $escape($appointment['estado']) ?></td><td><a href="<?= $user['role'] === 'Paciente' ? '/mis-citas/detalle' : '/citas/detalle' ?>?id=<?= $escape($appointment['id_cita']) ?>">Detalle</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php if ($history['clinical']): ?>
<section class="patient-card patient-detail-section"><h2 class="h5">Observaciones médicas</h2><?php if (!$history['notes']): ?><p class="text-secondary mb-0">No existen notas médicas registradas.</p><?php else: ?><div class="vstack gap-3"><?php foreach ($history['notes'] as $note): ?><article><strong><?= $escape($note['fecha_registro']) ?></strong><p class="mb-1"><?= nl2br($escape($note['observaciones'])) ?></p><small class="text-secondary"><?= $escape($note['medico_nombre']) ?></small></article><?php endforeach; ?></div><?php endif; ?></section>
<section class="patient-card patient-detail-section"><h2 class="h5">Tratamientos y recetas</h2><?php if (!$history['treatments']): ?><p class="text-secondary mb-0">No existen tratamientos o indicaciones registradas.</p><?php else: ?><div class="vstack gap-3"><?php foreach ($history['treatments'] as $treatment): ?><article><strong><?= $escape($treatment['fecha_registro']) ?></strong><p class="mb-1"><?= nl2br($escape($treatment['descripcion'])) ?></p><p class="mb-1"><?= nl2br($escape($treatment['indicaciones'] ?: 'Sin indicaciones')) ?></p><small class="text-secondary"><?= $escape($treatment['medico_nombre']) ?></small></article><?php endforeach; ?></div><?php endif; ?></section>
<?php endif; ?>
<section class="patient-card patient-detail-section"><h2 class="h5">Reprogramaciones y cancelaciones</h2><?php if (!$history['changes']): ?><p class="text-secondary mb-0">No existen cambios de cita registrados.</p><?php else: ?><div class="table-responsive"><table class="table patient-table mb-0"><thead><tr><th>Fecha</th><th>Tipo</th><th>Estado</th><th>Horario</th></tr></thead><tbody><?php foreach ($history['changes'] as $change): ?><tr><td><?= $escape($change['fecha_hora_cambio']) ?></td><td><?= $escape($change['tipo_cambio']) ?></td><td><?= $escape(($change['estado_anterior'] ?: '—').' → '.($change['estado_nuevo'] ?: '—')) ?></td><td><?= $escape(($change['fecha_anterior'] ?: '—').' '.($change['hora_inicio_anterior'] ?: '').' → '.($change['fecha_nueva'] ?: '—').' '.($change['hora_inicio_nueva'] ?: '')) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php if (\Clinica\Middleware\MedicalHistoryAccess::write($user)): ?><section class="patient-card patient-detail-section"><h2 class="h5">Registrar atención médica</h2><p class="text-secondary">Solo se habilita para citas con estado atendida. No se generan diagnósticos ni tratamientos automáticamente.</p><?php foreach ($history['appointments'] as $appointment): if ($appointment['estado'] !== 'atendida') continue; ?><div class="border-top pt-3 mt-3"><strong><?= $escape($appointment['fecha'].' · '.$appointment['medico_nombre']) ?></strong><form method="post" action="/citas/notas-medicas" class="mt-2"><input type="hidden" name="csrf" value="<?= $escape(\Clinica\Services\SessionService::csrf()) ?>"><input type="hidden" name="id_cita" value="<?= $escape($appointment['id_cita']) ?>"><label class="form-label" for="observaciones-<?= $escape($appointment['id_cita']) ?>">Observaciones</label><textarea class="form-control" id="observaciones-<?= $escape($appointment['id_cita']) ?>" name="observaciones" rows="3" required></textarea><button class="btn btn-clinic mt-2" <?= !\Clinica\Support\MedicalHistoryFactory::enabled() ? 'disabled' : '' ?>>Registrar nota</button></form><form method="post" action="/citas/tratamientos" class="mt-3"><input type="hidden" name="csrf" value="<?= $escape(\Clinica\Services\SessionService::csrf()) ?>"><input type="hidden" name="id_cita" value="<?= $escape($appointment['id_cita']) ?>"><label class="form-label" for="descripcion-<?= $escape($appointment['id_cita']) ?>">Tratamiento o receta</label><textarea class="form-control" id="descripcion-<?= $escape($appointment['id_cita']) ?>" name="descripcion" rows="2" required></textarea><label class="form-label mt-2" for="indicaciones-<?= $escape($appointment['id_cita']) ?>">Indicaciones</label><textarea class="form-control" id="indicaciones-<?= $escape($appointment['id_cita']) ?>" name="indicaciones" rows="2"></textarea><button class="btn btn-outline-primary mt-2" <?= !\Clinica\Support\MedicalHistoryFactory::enabled() ? 'disabled' : '' ?>>Registrar tratamiento</button></form></div><?php endforeach; if (!\Clinica\Support\MedicalHistoryFactory::enabled()): ?><div class="alert alert-info mt-3 mb-0">Las escrituras clínicas están deshabilitadas; no se modificará la base.</div><?php endif; ?></section><?php endif; ?>
